const MAX_REFRESH_ERROR_LENGTH = 2_000;

/**
 * Persists why the last refresh failed and reports whether the story was healthy
 * beforehand, so callers can notify only on the first failure of a streak.
 */
export async function recordStoryRefreshFailure(
	storyId: string,
	reason: StoryRefreshErrorReason,
	message: string,
): Promise<{ wasHealthy: boolean }> {
	const [previous] = await db
		.select({ lastRefreshError: s.story.lastRefreshError })
		.from(s.story)
		.where(eq(s.story.id, storyId))
		.limit(1)
		.execute();

	await db
		.update(s.story)
		.set({
			lastRefreshErrorReason: reason,
			lastRefreshError: message.slice(0, MAX_REFRESH_ERROR_LENGTH),
			lastRefreshErrorAt: new Date(),
		})
		.where(eq(s.story.id, storyId))
		.execute();

	return { wasHealthy: !previous?.lastRefreshError };
}

export async function clearStoryRefreshFailure(storyId: string): Promise<void> {
	await db
		.update(s.story)
		.set({ lastRefreshErrorReason: null, lastRefreshError: null, lastRefreshErrorAt: null })
		.where(and(eq(s.story.id, storyId), isNotNull(s.story.lastRefreshError)))
		.execute();
}

