/**
 * Refreshes a live story's query data and, when enabled, its narrative. The
 * outcome is always persisted on the story so viewers and the activity feed can
 * tell a stale story from a healthy one.
 */
export async function refreshStoryData(chatId: string, slug: string): Promise<RefreshResult> {
	const version = await storyQueries.getLatestVersionByChatAndSlug(chatId, slug);
	if (!version) {
		throw new Error('Story not found');
	}

	try {
		return await runStoryRefresh(chatId, slug, version);
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		await storyQueries.recordStoryRefreshFailure(version.storyId, 'query', message);
		throw error;
	}
}

async function runStoryRefresh(
	chatId: string,
	slug: string,
	version: Awaited<ReturnType<typeof storyQueries.getLatestVersionByChatAndSlug>> & object,
): Promise<RefreshResult> {
	const sqlQueries = await storyQueries.getSqlQueriesFromCode(chatId, version.code);
	if (Object.keys(sqlQueries).length === 0) {
		await storyQueries.clearStoryRefreshFailure(version.storyId);
		return { queryData: {}, narrativeFailure: null };
	}

	const chat = await chatQueries.getChatInfo(chatId);
	if (!chat) {
		throw new Error('Chat project not found');
	}

	const project = await projectQueries.retrieveProjectById(chat.projectId);
	if (!project.path) {
		throw new Error('Project path not configured');
	}

	const queryData: Record<string, { data: unknown[]; columns: string[] }> = {};

	await Promise.all(
		Object.entries(sqlQueries).map(async ([queryId, { sqlQuery, databaseId }]) => {
			const projectEnvVars = await projectQueries.getEnvVars(chat.projectId);
			const result = await executeRawSql(
				stripSqlFilterBlocks(sqlQuery),
				project.path!,
				databaseId,
				projectEnvVars,
			);
			queryData[queryId] = result;
		}),
	);

	let narrativeError: string | null = null;
	if (version.isLiveTextDynamic) {
		const generated = await generateDynamicStoryCode(
			{ projectId: chat.projectId, userId: chat.userId, chatId },
			version.title,
			version.code,
			queryData,
		);
		if (generated.code) {
			await storyQueries.updateLatestVersionCode(chatId, slug, generated.code);
		}
		narrativeError = generated.error;
	}

	await storyQueries.upsertStoryDataCache(chatId, slug, queryData);

	if (!narrativeError) {
		await storyQueries.clearStoryRefreshFailure(version.storyId);
		return { queryData, narrativeFailure: null };
	}

	const { wasHealthy } = await storyQueries.recordStoryRefreshFailure(version.storyId, 'narrative', narrativeError);
	return {
		queryData,
		narrativeFailure: { reason: 'narrative', message: narrativeError, isFirstFailure: wasHealthy },
	};
}

