export const STORY_REFRESH_FAILURE_REASONS = ['configuration', 'query', 'narrative', 'unknown'] as const;

export type StoryRefreshFailureReason = (typeof STORY_REFRESH_FAILURE_REASONS)[number];

export interface StoryRefreshFailure {
	reason: StoryRefreshFailureReason;
	message: string;
}

const reasonLabels: Record<StoryRefreshFailureReason, string> = {
	configuration: 'Story configuration',
	query: 'Query execution',
	narrative: 'Narrative generation',
	unknown: 'Unexpected error',
};

const reasonSummaries: Record<StoryRefreshFailureReason, string> = {
	configuration: 'The story is missing something it needs to refresh, such as a project path or a database.',
	query: 'One of the story queries could not be executed against the database.',
	narrative: 'The data was refreshed but the dynamic text could not be regenerated, so the narrative is stale.',
	unknown: 'The refresh stopped on an unexpected error.',
};

export function storyRefreshFailureLabel(reason: StoryRefreshFailureReason): string {
	return reasonLabels[reason] ?? reasonLabels.unknown;
}

export function storyRefreshFailureSummary(reason: StoryRefreshFailureReason): string {
	return reasonSummaries[reason] ?? reasonSummaries.unknown;
}

export function isStoryRefreshFailureReason(value: unknown): value is StoryRefreshFailureReason {
	return typeof value === 'string' && STORY_REFRESH_FAILURE_REASONS.includes(value as StoryRefreshFailureReason);
}

import type { StoryRefreshFailure, StoryRefreshFailureReason } from '@nao/shared/story-refresh';

/**
 * Carries the stage a refresh broke at so callers can persist why it failed,
 * not just the raw driver message.
 */
export class StoryRefreshError extends Error {
	readonly reason: StoryRefreshFailureReason;

	constructor(reason: StoryRefreshFailureReason, message: string, options?: { cause?: unknown }) {
		super(message, options);
		this.name = 'StoryRefreshError';
		this.reason = reason;
	}
}

export function toStoryRefreshFailure(error: unknown): StoryRefreshFailure {
	if (error instanceof StoryRefreshError) {
		return { reason: error.reason, message: error.message };
	}
	return { reason: 'unknown', message: error instanceof Error ? error.message : String(error) };
}

