export const getLatestStoryRefreshFailure = async (storyId: string): Promise<StoryRefreshFailureInfo | null> => {
	const [latest] = await db
		.select({
			id: s.activity.id,
			status: s.activity.status,
			trigger: s.activity.trigger,
			payload: s.activity.payload,
			errorMessage: s.activity.errorMessage,
			startedAt: s.activity.startedAt,
			completedAt: s.activity.completedAt,
		})
		.from(s.activity)
		.where(and(eq(s.activity.storyId, storyId), eq(s.activity.type, 'story.refreshed')))
		.orderBy(desc(s.activity.startedAt))
		.limit(1)
		.execute();

	if (!latest || (latest.status !== 'partial' && latest.status !== 'failed')) {
		return null;
	}

	const reason = latest.payload?.failureReason;
	return {
		activityId: latest.id,
		status: latest.status,
		reason: isStoryRefreshFailureReason(reason) ? reason : 'unknown',
		message: latest.errorMessage ?? 'The refresh failed.',
		trigger: latest.trigger,
		failedAt: latest.completedAt ?? latest.startedAt,
	};
};

