import type { StoryRefreshFailure } from '@nao/shared/story-refresh';

import * as activityQueries from '../queries/activity.queries';
import * as storyQueries from '../queries/story.queries';
import { toStoryRefreshFailure } from '../types/story-refresh';
import { logger } from '../utils/logger';

interface StoryRefreshOutcome {
	queriesRefreshed: number;
	failure: StoryRefreshFailure | null;
}

/**
 * Closes a running refresh activity. A degraded refresh is recorded as
 * `partial` so the story still reads as refreshed while keeping the reason it
 * is not fully up to date.
 */
export async function settleStoryRefreshActivity(activityId: string, outcome: StoryRefreshOutcome): Promise<void> {
	const payload = { queriesRefreshed: outcome.queriesRefreshed };
	if (!outcome.failure) {
		await activityQueries.completeActivity(activityId, payload);
		return;
	}

	await activityQueries.partiallyCompleteActivity(activityId, outcome.failure.message, {
		...payload,
		failureReason: outcome.failure.reason,
	});
}

export async function failStoryRefreshActivity(activityId: string, error: unknown): Promise<StoryRefreshFailure> {
	const failure = toStoryRefreshFailure(error);
	await activityQueries.failActivity(activityId, failure.message, {
		queriesRefreshed: 0,
		failureReason: failure.reason,
	});
	return failure;
}

/**
 * Records a refresh that failed outside of a tracked run — the on-demand
 * refresh triggered when an expired story is opened. Skipped when the story's
 * last refresh already failed, so repeated views don't flood the feed.
 */
export async function recordFailedStoryRefresh(chatId: string, slug: string, error: unknown): Promise<void> {
	try {
		const story = await storyQueries.getStoryByChatAndSlug(chatId, slug);
		if (!story) {
			return;
		}

		const existingFailure = await activityQueries.getLatestStoryRefreshFailure(story.id);
		if (existingFailure) {
			return;
		}

		const projectId = story.projectId ?? (await storyQueries.getStoryProjectId(story.id));
		if (!projectId) {
			return;
		}

		const failure = toStoryRefreshFailure(error);
		await activityQueries.createActivity({
			projectId,
			userId: story.userId ?? (await storyQueries.getStoryOwnerId(story.id)),
			type: 'story.refreshed',
			trigger: 'system',
			status: 'failed',
			storyId: story.id,
			chatId: story.chatId,
			payload: { queriesRefreshed: 0, failureReason: failure.reason },
			errorMessage: failure.message,
			completedAt: new Date(),
		});
	} catch (recordError) {
		const message = recordError instanceof Error ? recordError.message : String(recordError);
		logger.error(`Failed to record story refresh failure: ${message}`, {
			source: 'system',
			context: { chatId, slug },
		});
	}
}

