interface NotifyInput {
	story: DBStory;
	ownerId: string;
	failure: StoryRefreshFailure;
	refreshStartedAt: Date;
	isPartial: boolean;
}

/**
 * Emails the story owner when a scheduled refresh breaks. Only the first
 * failure of a streak is sent, so a story that stays broken doesn't email on
 * every scheduled tick.
 */
export async function notifyStoryRefreshFailure(input: NotifyInput): Promise<void> {
	if (!emailService.isEnabled()) {
		return;
	}

	try {
		const previousStatus = await activityQueries.getPreviousStoryRefreshStatus(
			input.story.id,
			input.refreshStartedAt,
		);
		if (previousStatus === 'failed' || previousStatus === 'partial') {
			return;
		}

		const owner = await userQueries.getUser({ id: input.ownerId });
		if (!owner) {
			return;
		}

		await emailService.sendEmail(
			owner.email,
			buildStoryRefreshFailedEmail(
				owner,
				{
					title: input.story.title,
					url: buildStoryUrl(input.story),
					scheduleDescription: input.story.cacheScheduleDescription ?? input.story.cacheSchedule,
				},
				input.failure,
				{ failedAt: new Date(), isPartial: input.isPartial },
			),
		);
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		logger.error(`Failed to notify story refresh failure: ${message}`, {
			source: 'system',
			context: { storyId: input.story.id },
		});
	}
}

function buildStoryUrl(story: DBStory): string {
	return story.chatId
		? `${env.BETTER_AUTH_URL}/stories/preview/${story.chatId}/${story.slug}`
		: `${env.BETTER_AUTH_URL}/stories/standalone/${story.id}`;
}

