+					Default model
+				</label>
+				<Select
+					value={selectedValue}
+					onValueChange={handleModelChange}
+					disabled={!isAdmin || agentSettings.isLoading || availableModels.isLoading || updateAgentSettings.isPending}
+				>
+					<SelectTrigger id='live-story-refresh-model' className='w-full'>
+						<SelectValue>
+							<div className='flex min-w-0 items-center gap-2'>
